/* Phone layout fixes: full-width hero actions, stacked cards, stacked signup */
@media (max-width: 760px){
  .pavilion__choices{grid-template-columns:1fr !important;grid-auto-flow:row !important;grid-auto-columns:1fr !important;gap:10px}
  .pavilion__control{min-height:48px;padding:12px 16px;font-size:16px;width:100%}
  .pavilion__offers{flex-direction:column !important;flex-flow:column !important}
  .pavilion__item{flex:none;min-width:0 !important;width:100%}
  .pavilion__signup{grid-template-columns:1fr !important;max-width:100%}
  .pavilion__address{width:100%;min-height:48px;font-size:16px}
}

/* Phone layout fixes (320–430px) */
@media (max-width: 760px) {
  .dovetail__container .dovetail__headline {
    white-space: normal;
    overflow-wrap: anywhere;
    font-size: clamp(28px, 9vw, 40px);
    line-height: 1.12;
  }
  .dovetail__container .dovetail__signup {
    grid-template-columns: 1fr;
    max-width: 100%;
  }
  .dovetail__container .dovetail__signup .dovetail__address {
    width: 100%;
    min-width: 0;
  }
  .dovetail__container .dovetail__signup .dovetail__control {
    width: 100%;
  }
  .dovetail__container .dovetail__offers {
    flex-direction: column;
    flex-flow: column;
  }
  .dovetail__container .dovetail__item {
    min-width: 0;
    flex: 1 1 auto;
  }
}

/* Phone layout: vertical hero, full-width actions, contained preview */
@media (max-width: 760px) {
  .tracework__intro {
    flex-direction: column;
    align-items: stretch;
    gap: 16px;
  }
  .tracework__message {
    min-width: 0;
    min-inline-size: 0;
    flex: 1 1 auto;
  }
  .tracework__choices {
    grid-auto-flow: row;
    grid-auto-columns: 1fr;
    grid-template-columns: 1fr;
    gap: 10px;
  }
  .tracework__control {
    min-height: 48px;
    width: 100%;
    padding: 12px 14px;
    font-size: 16px;
    line-height: 1.3;
  }
  .tracework__display {
    flex: 0 1 auto;
    min-width: 0;
    width: 100%;
    padding: 10px;
  }
  .tracework__graphic {
    min-inline-size: 0;
    inline-size: 100%;
    width: 100%;
    height: auto;
    max-width: 100%;
  }
}

/* Phone layout fixes: keep preview inside panel, full-width hero actions, readable headline */
@media (max-width: 760px){
  .sunroom__container .sunroom__graphic{min-inline-size:0;inline-size:100%;max-inline-size:100%}
  .sunroom__container .sunroom__choices{grid-template-columns:1fr;grid-auto-flow:row;grid-auto-columns:1fr}
  .sunroom__container .sunroom__control{min-height:44px;width:100%;padding:12px 14px;font-size:16px;line-height:1.3}
  .sunroom__container .sunroom__headline{white-space:normal;overflow-wrap:anywhere;font-size:clamp(28px,8vw,37px)}
}

/* Phone layout fixes: stack cards, hero, and signup */
@media (max-width: 760px){
  .nightjar__offers{flex-direction:column;flex-wrap:wrap}
  .nightjar__item{flex:1 1 auto;min-width:0;width:100%}
  .nightjar__intro{flex-direction:column;flex-wrap:wrap;flex-flow:column;align-items:stretch}
  .nightjar__message{min-inline-size:0;min-width:0;width:100%}
  .nightjar__display{width:100%}
  .nightjar__signup{grid-template-columns:1fr;grid-template-columns:1fr;max-width:100%}
  .nightjar__address{width:100%;min-width:0}
}
